        int[] ref = {1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5};
        for (int f = 3; f <= 4; f++) {
            Deque<Integer> q = new ArrayDeque<>();
            int faults = 0;
            for (int p : ref) {
                if (!q.contains(p)) {
                    faults++;
                    if (q.size() == f) q.poll();
                    q.add(p);
                }
            }
            System.out.println(faults);
        }
    }
}

