import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int f = in.nextInt();
        int n = in.nextInt();
        LinkedList<Integer> frames = new LinkedList<>();
        int faults = 0;
        for (int i = 0; i < n; i++) {
            Integer p = in.nextInt();
            if (frames.remove(p)) {
                frames.addLast(p);
            } else {
                faults++;
                if (frames.size() == f) frames.removeFirst();
                frames.addLast(p);
            }
        }
        System.out.println(faults);
    }
}

